package ai.fitnova.service;
import ai.fitnova.api.ApiDtos.*; import ai.fitnova.domain.*; import ai.fitnova.repo.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class ActivityService {private final MealRepository meals;private final FormSessionRepository forms;private final WorkoutRepository workouts;private final ReadinessService readiness;private final WorkoutService workoutService;
 @Transactional public MealView saveMeal(User u,MealRequest r){Meal m=new Meal();m.setUser(u);m.setName(r.name());m.setGoal(r.goal());m.setIngredients(String.join("|",r.ingredients()));m.setInstructions(String.join("|",r.instructions()));m.setCalories(r.calories());m.setProteinG(r.proteinG());m.setPrepMinutes(r.prepMinutes());return mealView(meals.save(m));}
 public List<MealView> meals(User u){return meals.findTop30ByUserIdOrderByCreatedAtDesc(u.getId()).stream().map(this::mealView).toList();}
 @Transactional public FormSessionView saveForm(User u,FormSessionRequest r){FormSession f=new FormSession();f.setUser(u);f.setExercise(r.exercise());f.setReps(r.reps());f.setScore(r.score());f.setBestScore(r.bestScore());f.setDurationSeconds(r.durationSeconds());f.setFeedback(String.join("|",r.corrections()==null?List.of():r.corrections()));return formView(forms.save(f));}
 public List<FormSessionView> forms(User u){return forms.findTop30ByUserIdOrderByCreatedAtDesc(u.getId()).stream().map(this::formView).toList();}
 public ProgressView progress(User u){var ws=workouts.findTop30ByUserIdOrderByIdDesc(u.getId());var completed=ws.stream().filter(w->"COMPLETED".equals(w.getStatus())).toList();var rs=readiness.trend(u);var fs=forms(u);Integer avgR=rs.isEmpty()?null:(int)Math.round(rs.stream().mapToInt(ReadinessView::score).average().orElse(0));Integer avgF=fs.isEmpty()?null:(int)Math.round(fs.stream().mapToInt(FormSessionView::score).average().orElse(0));return new ProgressView(completed.size(),completed.stream().mapToInt(Workout::getDurationMinutes).sum(),streak(completed),avgR,avgF,rs,fs);}
 public DashboardView dashboard(User u,boolean onboardingComplete){var ws=workouts.findTop30ByUserIdOrderByIdDesc(u.getId());var completed=ws.stream().filter(w->"COMPLETED".equals(w.getStatus())).toList();var fs=forms(u);Integer avgF=fs.isEmpty()?null:(int)Math.round(fs.stream().mapToInt(FormSessionView::score).average().orElse(0));WorkoutView today=ws.stream().filter(w->!"COMPLETED".equals(w.getStatus())).findFirst().map(workoutService::view).orElse(null);return new DashboardView(new UserView(u.getId(),u.getFullName(),u.getEmail(),onboardingComplete),readiness.latest(u),today,new Summary(completed.size(),completed.stream().mapToInt(Workout::getDurationMinutes).sum(),streak(completed),avgF),ws.stream().limit(5).map(workoutService::view).toList());}
 private int streak(List<Workout> ws){return (int)ws.stream().map(Workout::getCompletedAt).filter(Objects::nonNull).map(x->x.atZone(java.time.ZoneOffset.UTC).toLocalDate()).distinct().count();}
 private MealView mealView(Meal m){return new MealView(m.getId(),m.getName(),m.getGoal(),split(m.getIngredients()),split(m.getInstructions()),m.getCalories(),m.getProteinG(),m.getPrepMinutes(),m.getCreatedAt());}
 private FormSessionView formView(FormSession f){return new FormSessionView(f.getId(),f.getExercise(),f.getReps(),f.getScore(),split(f.getFeedback()),f.getCreatedAt());}
 private List<String> split(String s){return s==null||s.isBlank()?List.of():Arrays.asList(s.split("\\|"));}}
